def add_section(doc,marker,paragraph,table,figure):
    if marker=='Q1_COUPLED_OBSERVATION':
        paragraph(doc,'The same invariance holds for coupled linear compliance. Let H be symmetric positive definite. The force-constrained contact solution uniquely minimizes the strictly convex potential')
        p=paragraph(doc,'');p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        p._p.append(node('oMath',seq('Ψ(p) = ',frac('1','2'),sup('p','T'),'H p + ',sup('g','T'),'p;   p ≥ 0, ',sup('1','T'),'p = F')))
        paragraph(doc,'Its KKT conditions are w=Hp+g−δ1≥0 and pᵢwᵢ=0. If Δg≥0 and Δgᵢ=0 at every positive-force contact, the same p and δ satisfy the modified conditions. Uniqueness establishes unchanged approach even with cross-pair elastic coupling. For two load-controlled solutions, the variational inequalities give')
        p=paragraph(doc,'');p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        p._p.append(node('oMath',seq(sup('(p₂ − p₁)','T'),'H(p₂ − p₁) ≤ (δ₂ − δ₁)(F₂ − F₁)')))
        paragraph(doc,'The inequality implies strict increase of total force with approach on a loaded branch; it does not imply monotonic increase of every individual contact force. An added nonlinear Hertz term requires positive definiteness of H+diag(w′_H) over the force domain. For the clipped law, λ_min(H)>2 max Kᵢ is sufficient. The FE contact used below has no additional Hertz spring. All versions of this argument retain fixed compliance, stations and normals.')
        return
    if marker=='Q1_CROSS_INVERSE':
        cross=old('03_cross_inverse.json');mc=old('04_mc_summary.json')
        paragraph(doc,'For the 57/57 pair at 650 Nm, nineteen interior phases of a 25-phase FE calculation are used after excluding six restricted phases. The minimum loaded coordinate over the retained phases is 0.6953, above the tested dedendum starts 0.30 and 0.45. Combined-relief and addendum-only curves are identical. This verifies the support prediction within a coupled, fixed-compliance FE gap model; the shared nominal sections limit its independence as a test of physical material removal.')
        rows=[[r['variant'],r['case'],f"{r['estimate'][0]:.4f}",f"{r['estimate'][1]:.4f}",f"{r['estimate'][2]:.4f}",f"{r['estimate'][3]:.2f}",f"{r['rmse_TE_at_observed_phases_um']:.3f}",f"{r['pp_pred_um']:.2f} / {r['pp_fe_um']:.2f}"] for r in cross['rows']]
        paragraph(doc,'Table 9 Analytical inversion of the 57/57 interior FE observations. Depths are mm; residual and predicted versus FE sampled range are µm. The dedendum estimates retain their initial values because no dedendum signal is present.')
        table(doc,['Variant','Case','Cₐ','sₐ','C_d','s_d','TE RMS','Range pred/FE'],rows,[2.1,2.1,1.5,1.4,1.5,1.4,2,3.6])
        paragraph(doc,'Addendum depth errors are approximately 2.5 µm for the baseline and 0.6 µm for radial energy, with TE residuals of 0.109–0.151 µm. Dedendum coordinates that remain at their initialization carry no geometrical information. A residual in TE units is not a bound on profile accuracy; such a bound would also require inverse stability and a discrepancy model.')
        supplementary('S10','57/57 fixed-section cross-operator inversion. Nineteen common interior phases; values of an inactive dedendum block depend on initialization.',['Variant','Case','Estimate (Cₐ,sₐ,C_d,s_d)','TE RMS µm'],[[r['variant'],r['case'],theta(r['estimate']),f"{r['rmse_TE_at_observed_phases_um']:.3f}"] for r in cross['rows']],[2.7,2.6,8.4,2.7])
        supplementary('S11','Formulation dependence of internal noise recovery. Each cell uses 100 realizations, σ=0.1 µm, 300 Nm and 120 positions; parameter errors use the declared scales.',['Variant','True s_d','Addendum med.','Dedendum med.','Profile RMS µm'],[[r['variant'],r['sd_true'],f"{r['addendum_scaled_error']['median']:.3f}",f"{r['dedendum_scaled_error']['median']:.3f}",f"{r['full_profile_rmse_um']['median']:.3f}"] for r in mc['summary']],[3.1,1.8,3.7,3.7,4.1])
        audit=read('audit_inverse.json');archive=old('11_fe_observable_dedendum.json')
        pe=next(r for r in audit['variants'] if r['variant']=='projected-energy')
        paragraph(doc,'The 24/24 test uses m=3 mm, b=20 mm, 300 Nm and true θ=(0.020,0.75,0.010,0.50). Of 120 phases, 102 share unrestricted contact patches. A minimum loaded coordinate below 0.50 establishes overlap at some sampled contacts, rather than penetration at every phase. The combined-relief response differs from the nominal profile by 1.7684 µm RMS, and the addendum-only response by 1.7876 µm. Isolating dedendum requires subtracting the latter from the former: the signal is 0.1790 µm RMS, compared with 0.1966 µm for radial energy, a ratio of 0.910. The combined-versus-nominal contrast does not measure dedendum sensitivity.')
        original=next(r for r in archive['rows'] if r['variant']=='projected-energy')
        paragraph(doc,f"A two-start radial-energy inversion estimates θ={theta(original['noiseless']['estimate'])}, with a dedendum-depth error of {1000*abs(original['noiseless']['estimate'][2]-.01):.4f} µm but a start error of {abs(original['noiseless']['estimate'][3]-.5):.4f}. Its full-profile RMS error is {original['noiseless']['profile_rmse_um']:.3f} µm, compared with a TE residual of {original['noiseless']['fit_rmse_um']:.3f} µm. Over 50 noise realizations, the median profile RMS error is {original['mc']['profile_rmse_median_um']:.3f} µm. These profile errors preclude treating a close depth estimate as validation of the complete relief shape.")
        paragraph(doc,'The restricted comparison uses 26 fixed and broadly distributed starts per fit. Depth profiles cover 41 values and start profiles 46 values, with five starts per point. The assumed objective scale is 0.1 µm; under cross-operator discrepancy, objective increases are conditional diagnostics rather than calibrated physical significance levels.')
        for r in audit['variants']:
            b=r['best'];n=r['restricted']
            paragraph(doc,f"The {r['variant']} formulation gives θ={theta(b['theta'])}, a TE residual of {b['fit_rmse_um']:.4f} µm and profile RMS error {r['best_profile_rmse_um']:.3f} µm. Fixing C_d=0 and the redundant s_d gives residual {n['fit_rmse_um']:.4f} µm and objective increase Δχ²={r['delta_chi2_no_dedendum']:.4g} (Figure 7).")
        paragraph(doc,'Neither formulation distinguishes the presence of dedendum relief in these data: the null-model objective increases are below 10⁻⁶. Both depth profiles remain flat over 0–50 µm and both start profiles over 0.05–0.50 at the numerical resolution of the search. At each broad-start optimum, the dedendum Jacobian columns vanish and the numerical rank is two. The same holds for the two-start radial-energy fit: s_d=0.300621 is below its first loaded coordinate 0.303605. Deleting its fitted dedendum leaves the predicted TE exactly unchanged. The near-true depth is consequently one arbitrary value in an invariant fit set, rather than evidence of depth recovery. A nonzero signal in the FE generator has not translated into identifiable relief in the inverse operator.')
        figure(doc,'fig_fe_inverse_v11.png','Figure 7 Cross-operator uncertainty for the 24/24 gap test. Profile objectives refit the remaining parameters; 3.841 is an uncalibrated nominal reference. Lower panels compare full-flank profiles and TE residuals at retained interior phases. Curves above the displayed objective range remain available in the numerical records.')
        mesh=read('mesh_convergence.json');rs=mesh['rows']
        paragraph(doc,'A dedicated bulk-mesh study uses h=0.50, 0.35 and 0.25 mm with P1 elements, the same 102 interior phases and fixed 0.02 mm nodal contact spacing. For each level, both the isolated dedendum response and the radial-energy inverse are recomputed. This controls bulk discretization for the actual inversion geometry while keeping the interface and nominal contour fixed; it is not a contact-interface or physically modified-geometry convergence certificate.')
        paragraph(doc,'Across these levels, isolated dedendum signals are '+', '.join(f"{r['isolated_dedendum_rms_um']:.5f}" for r in rs)+' µm RMS and inverse TE residuals are '+', '.join(f"{r['fit_rmse_um']:.5f}" for r in rs)+' µm. Supplementary Table S16 reports the associated parameter and profile errors. Parameter stability is interpreted separately from forward-signal stability, because a flat inverse objective can amplify small discretization changes.')
        change=100*abs(rs[-1]['fit_rmse_um']/rs[-2]['fit_rmse_um']-1)
        paragraph(doc,f"The isolated signal changes by only {100*abs(rs[-1]['isolated_dedendum_rms_um']/rs[-2]['isolated_dedendum_rms_um']-1):.4f}% on the last refinement, whereas the inverse residual changes by {change:.2f}%. The arbitrary dedendum estimates and full-profile errors also vary. Thus this sequence supports stability of the isolated response contrast, but does not establish mesh-independent inverse recovery. A converged inversion is not claimed.")
        supplementary('S13','24/24 two-start inversion archived with the FE test. Correct isolated FE dedendum signal is 0.178987 µm RMS; nominal and combined profiles share addendum relief. Profile errors use 1001 full-flank coordinates. MC uses 50 realizations and σ=0.1 µm.',['Variant','Noiseless estimate','TE RMS µm','Profile RMS µm','MC profile median µm','MC profile p90 µm'],[[r['variant'],theta(r['noiseless']['estimate']),f"{r['noiseless']['fit_rmse_um']:.4f}",f"{r['noiseless']['profile_rmse_um']:.4f}",f"{r['mc']['profile_rmse_median_um']:.4f}",f"{r['mc']['profile_rmse_p90_um']:.4f}"] for r in archive['rows']],[2.1,5.3,2.1,2.3,2.3,2.3])
        supplementary('S14','Broad-start and restricted inversions of the 24/24 FE observations. Each unrestricted and null fit uses 26 starts. The null fixes C_d=0 and redundant s_d=0.50. Δχ² uses an assumed 0.1 µm scale and is not a calibrated physical test.',['Variant','Broad-start estimate','TE RMS µm','Profile RMS µm','Null TE RMS µm','Null Δχ²'],[[r['variant'],theta(r['best']['theta']),f"{r['best']['fit_rmse_um']:.5f}",f"{r['best_profile_rmse_um']:.4f}",f"{r['restricted']['fit_rmse_um']:.5f}",f"{r['delta_chi2_no_dedendum']:.6g}"] for r in audit['variants']],[2.1,5.3,2.1,2.3,2.3,2.3])
        profiles=[]
        for r in audit['variants']:
            for key,rr in r['profiles'].items():
                acc=[a['value'] for a in rr if a['delta_chi2']<=3.841];factor=1000 if key=='Cd' else 1
                profiles.append([r['variant'],key,len(rr),f"{min(acc)*factor:.4g}–{max(acc)*factor:.4g}" if acc else 'None',f"{max(a['delta_chi2'] for a in rr):.5g}",sum(not a['success'] for a in rr)])
        supplementary('S15','Profile-objective diagnostics for the 24/24 gap data. Each point uses five starts. Extrema below 3.841 are sampled diagnostics, not confidence limits; depth is in µm and start is dimensionless.',['Variant','Parameter','Points','Grid extrema','Max Δχ²','Failed fits'],profiles,[3,2.5,2,4.2,2.7,2])
        supplementary('S16','Dedicated 24/24 bulk-mesh sensitivity at fixed 0.02 mm nodal interface, P1 elasticity, nominal contour and 102 common interior phases. Each inverse uses twelve starts. Last-step changes do not certify an asymptotic rate or interface convergence.',['h mm','Isolated signal µm','Estimate','TE RMS µm','Profile RMS µm'],[[r['h_mm'],f"{r['isolated_dedendum_rms_um']:.6f}",theta(r['estimate']),f"{r['fit_rmse_um']:.5f}",f"{r['profile_rmse_um']:.4f}"] for r in rs],[1.4,2.6,7.4,2.5,2.5])
        return
    if marker=='Q1_RESOLUTION':
        a=read('audit_structure.json')['null_space'];oldres=old('07_resolution.json');prec=old('09_resolution_corrections.json')['precision']
        paragraph(doc,'A piecewise-linear relief field on 41 uniform nodes replaces the four-parameter family. At G0, 300 Nm, 120 observations and the marginal-support truth, the whitened tangent J_h=σ⁻¹∂F/∂h has size 120×41. We compute R=V diag[sₖ²/(sₖ²+ε²)]Vᵀ, with ε=10⁻⁶s₁, from its SVD. The diagonal describes damped resolution in that basis; it is not a probability of physical recovery.')
        paragraph(doc,f"The recomputed matrix has rank {a['rank']} and ten null directions. Nine columns vanish for nodes ξ≤0.20. The first sensitive node is ξ={a['first_sensitive_node']:.3f}, below the minimum sampled contact ξ={a['minimum_loaded_coordinate']:.6f}, because its hat function extends into loaded support. Thus a sensitive nodal coordinate need not itself be a contact point. The interpolation-basis support, rather than the nodal coordinate alone, determines a zero column.")
        paragraph(doc,'The remaining null direction is a constant over the 32 sensitive coefficients. Their hat functions sum to one at loaded contacts, so that direction shifts approach uniformly and is removed by centring. Numerically ‖J_h1‖/s₁≈5.5×10⁻¹⁶. In this particular discretization the resolved-subspace projector has diagonal 1−1/32 on sensitive coefficients and zero on the other nine; the damped resolution diagonal approximates it. Equality of rank to the number of sensitive coefficients minus one is a verified result for these grids, not a theorem for every sampling scheme.')
        paragraph(doc,'At σ=0.1 µm, 26 of the 31 resolved singular directions have conditional standard deviation below 1 µm; the two weakest have 5.26 and 14.69 µm. These are local linearized uncertainties after excluding null directions and assuming the stated independent noise, fixed mechanics and fixed gauge. They do not quantify absolute nodal uncertainty or uncertainty from mechanical discrepancy. Precision is heterogeneous within loaded support, even where the resolution diagonal is near one.')
        paragraph(doc,'A uniform 5 µm gap shift changes centred TE only at numerical roundoff. Finite perturbations supported on an unloaded basis function also leave the tested responses unchanged. Such examples verify particular finite invariances; arbitrary SVD null directions remain first-order statements unless their finite perturbations preserve the active-set and gap hypotheses. Supplementary Table S12 reports refinement of flank and angular grids.')
        figure(doc,'fig_resolution_v11.png','Figure 8 Resolution and conditional precision of the discretized relief. Basis support explains sensitivity at a node below the first contact. The singular spectrum and resolved-direction standard deviations refer to the local operator with σ=0.1 µm; null-direction uncertainty is not finite.')
        rows=[]
        for key in ['120_41','240_41','240_81','480_81']:
            r=oldres['refinement'][key];rows.append([r['n_positions'],r['n_nodes'],r['zero_columns'],r['numerical_rank'],r['null_dim'],f"{r['min_range_singular_value']:.4g}"])
        supplementary('S12','Resolution refinement of the local discretized operator. Zero columns follow the support of basis functions. The additional constant is annihilated by mean removal.',['Positions','Nodes','Zero columns','Rank','Null dimension','Smallest resolved s'],rows,[2.4,1.8,2.8,1.8,2.8,4.8])
        return
    for text in TEXT[marker]:paragraph(doc,text)
    # Preserve numerical tables and figures, replacing all inherited narrative.
    def captions(d,text):
        if text.startswith(('Table ','Figure ','Supplementary Table ')):
            if text.startswith('Figure 6 '):text='Figure 6 Full scaled whitened singular spectra at 120 positions and σ=0.1 µm. Marginal smallest singular values are grid dependent; see Supplementary Tables S2–S4.'
            return paragraph(d,text)
        return None
    previous.add_section(doc,marker,captions,table,figure)
